                # Diagonal runs sloping down-right encode invariant c-r.
                samples[c-r] = grid[r][c]
    # Fit a period from repeated equal-color diagonal samples, minimizing p.
    if samples:
        ds = list(samples)
        period = None
        for p in range(1, max(h, w)*2+1):
            if all(samples[a] == samples[b] for a in ds for b in ds if (a-b) % p == 0):
                period = p
                break
