                candidates = [grid[r][c] for c in range(w) if grid[r][c]]
                if candidates:
                    row_colors[r] = candidates[0]
            # Choose shortest compatible period over row samples.
            for p in range(1, h+1):
                if all(row_colors[a] == row_colors[b] for a in row_colors for b in row_colors if (a-b)%p==0):
                    table={r%p:v for r,v in row_colors.items()}
                    return [[table.get(r%p, 0)]*w for r in range(h)]
    # Uniform horizontal-row demonstrations encode a repeated row sequence.
    rows={r:row[0] for r,row in enumerate(grid) if len(set(row))==1 and row[0]!=0}
    for p in range(1,h+1):
        if rows and all(rows[a]==rows[b] for a in rows for b in rows if (a-b)%p==0):
            table={r%p:v for r,v in rows.items()}
            return [[table.get(r%p,0)]*w for r in range(h)]
    return [row[:] for row in grid]
