def transform(grid):
    h, w = len(grid), len(grid[0])
    # Horizontal bars encode a vertical periodic sequence; copy its observed
    # cycle through the full height (including the rows before first sample).
    bars = {r: row[0] for r, row in enumerate(grid)
            if len(set(row)) == 1 and row[0] != 0}
    if bars:
        for p in range(1, h + 1):
            if all(bars[a] == bars[b] for a in bars for b in bars
                   if (a - b) % p == 0):
                phase = {r % p: color for r, color in bars.items()}
                return [[phase[r % p]] * w for r in range(h)]

    # Parallel down-right diagonals encode colors by the invariant c-r.
    marks = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                marks[c-r] = grid[r][c]
    ds = list(marks)
    for p in range(1, h + w + 1):
        if all(marks[a] == marks[b] for a in ds for b in ds
               if (a - b) % p == 0):
            phases = {d % p: color for d, color in marks.items()}
            # Demos show a complete encoded cycle; fill each parallel stripe.
            return [[phases[(c-r) % p] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
